*{box-sizing:border-box} :root{--ink:#f2e9d8;--muted:#a19b8b;--dim:#746f63;--gold:#e5b45d;--gold2:#bf8540;--green:#182523;--panel:#1a2825;--line:rgba(222,198,150,.16);--serif:'Playfair Display',Georgia,serif;--sans:'DM Sans',sans-serif;--mono:'DM Mono',monospace} html,body{margin:0;min-height:100%;background:#101a19;color:var(--ink);font-family:var(--sans)}body{min-height:100vh;background:radial-gradient(ellipse at 42% 3%,#24312b 0,#15211f 46%,#101817 100%);overflow-x:hidden}.app-shell{max-width:1450px;margin:0 auto;padding:0 40px}.topbar{height:80px;border-bottom:1px solid rgba(220,198,154,.12);display:flex;align-items:center;position:relative}.brand{display:flex;align-items:center;gap:11px;color:#f0e5cf;text-decoration:none;font-size:15px;font-weight:800;letter-spacing:2px}.brand-mark{width:29px;height:29px;border:1px solid rgba(226,177,91,.62);display:grid;place-items:center;color:var(--gold);font-size:17px}.brand-light{color:#b1aa97;font-weight:500}.chapter{position:absolute;left:50%;transform:translateX(-50%);display:flex;flex-direction:column;align-items:center;gap:3px}.chapter-kicker{font:9px var(--mono);letter-spacing:2px;color:#93866b}.chapter-name{font:14px var(--serif);letter-spacing:.3px}.top-actions{margin-left:auto;display:flex;align-items:center;gap:17px}.sound-chip{font:9px var(--mono);letter-spacing:1.5px;color:#9eaa98}.live-dot{display:inline-block;width:6px;height:6px;background:#a5bb76;border-radius:50%;margin-right:7px;box-shadow:0 0 8px #9abd69}.icon-btn{width:28px;height:28px;border:1px solid rgba(215,195,156,.25);border-radius:50%;background:none;color:#b9b19e;font:13px var(--serif);cursor:pointer}.icon-btn:hover,.deck-help:hover{border-color:var(--gold);color:var(--gold)}.game-layout{display:grid;grid-template-columns:minmax(0,1.72fr) minmax(340px,.93fr);gap:30px;padding:31px 0 24px}.battle-column{min-width:0}.battle-heading{height:69px;display:flex;justify-content:space-between;align-items:flex-start}.eyebrow{display:flex;align-items:center;gap:9px;color:#ac9360;font:9px var(--mono);letter-spacing:2px}.eyebrow-line{height:1px;width:19px;background:#ae8a4d}.battle-heading h1{font:700 29px var(--serif);line-height:1.15;letter-spacing:-.4px;margin:7px 0 0;color:#f0e6d5}.battle-heading h1 em,.modal h2 em{font-weight:600;color:#d4a959}.battle-state{align-self:flex-end;margin-bottom:12px;display:flex;align-items:center;gap:7px;color:#c4b998;font:9px var(--mono);letter-spacing:1.1px}.state-icon{color:#d6a957;font-size:13px}.board-frame{border:1px solid rgba(220,191,133,.25);background:#17211e;padding:9px;box-shadow:0 15px 40px #090f0e77;position:relative}.board-topline,.board-legend{height:29px;display:flex;align-items:center;justify-content:space-between;padding:0 9px;color:#a89c7f;font:9px var(--mono);letter-spacing:1.3px}.tiny-star{font-style:normal;color:var(--gold);font-size:12px;margin-right:5px}.threat-label{display:flex;align-items:center;gap:7px;color:#8e9180}.threat-label i{width:5px;height:5px;border-radius:100%;background:#c78b4b;box-shadow:0 0 6px #cc8e44}.threat-label b{color:#edc16f}.canvas-wrap{position:relative;width:100%;aspect-ratio:1.78;background:#24372c;overflow:hidden;border:1px solid rgba(222,199,147,.18)}canvas{display:block;width:100%;height:100%;cursor:crosshair}.canvas-tip{position:absolute;left:50%;bottom:12px;transform:translateX(-50%);white-space:nowrap;padding:8px 13px;background:rgba(12,21,18,.82);border:1px solid rgba(231,195,122,.24);color:#e2cf9f;font:9px var(--mono);letter-spacing:1.4px;pointer-events:none;transition:opacity .3s}.canvas-tip span{color:var(--gold);margin-right:5px}.canvas-tip.hidden{opacity:0}.wave-banner{position:absolute;top:15px;left:50%;transform:translateX(-50%);padding:10px 22px;background:#17231ecc;border:1px solid #dcb35b88;color:#f2d594;font:10px var(--mono);letter-spacing:2px;box-shadow:0 5px 25px #0b130e88;animation:banner-in .3s ease-out;pointer-events:none}.wave-banner b{font-weight:500;color:#fff4d7}.hidden{display:none!important}@keyframes b