,198,154,.16);padding:14px 16px}.panel-label{color:#a39779;font:9px var(--mono);letter-spacing:1.5px}.ornament{float:right;color:#c59d58}.resources{display:flex;align-items:center;padding-top:13px}.resource{display:flex;align-items:center;gap:10px;flex:1}.resource-icon{font-size:22px;line-height:1}.resource-icon.gold{color:#dfae55}.resource-icon.heart{color:#d17e67;font-size:19px}.resource div{display:flex;flex-direction:column;gap:2px}.resource b{font:700 20px var(--serif);line-height:1;color:#f0e2c7}.resource small{font:8px var(--mono);letter-spacing:1px;color:#8d9789}.resource-divider{height:34px;width:1px;background:rgba(220,198,154,.17);margin:0 17px}.resource-change{font:10px var(--mono);color:#b5cc7d}.mission-panel{padding-bottom:10px}.intel-icon{float:right;font-size:16px;color:#b29c67}.mission-row{display:flex;gap:11px;padding:13px 0 11px}.mission-symbol{width:28px;height:28px;display:grid;place-items:center;border:1px solid #b1935a55;color:#d4ab66;font-size:13px;flex-shrink:0}.mission-row b{font:600 12px var(--serif);color:#e6dbc4}.mission-row p{font-size:10px;line-height:1.45;color:#9da194;margin:4px 0 0;max-width:260px}.mission-footer{border-top:1px solid rgba(220,198,154,.12);padding-top:9px;display:flex;justify-content:space-between;color:#868d80;font:8px var(--mono);letter-spacing:1px}.mission-footer b{color:#d9bd80;font-size:10px}.deck-panel{flex:1;background:rgba(22,34,31,.65);border:1px solid rgba(220,198,154,.16);padding:14px 14px 10px;min-height:0}.deck-heading{display:flex;justify-content:space-between;align-items:flex-start}.deck-count{color:#d0aa63;margin-left:5px}.deck-heading p{color:#8e9486;font-size:10px;margin:6px 0 0}.deck-help{width:18px;height:18px;border:1px solid rgba(220,198,154,.35);border-radius:50%;background:none;color:#bcb094;font:10px var(--serif);cursor:pointer}.hand{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:8px;margin-top:12px}.tower-card{padding:7px 7px 8px;min-width:0;position:relative;text-align:left;background:linear-gradient(160deg,#2c3730,#222d29 60%,#1e2926);border:1px solid rgba(203,182,139,.24);color:#e7dec9;cursor:pointer;transition:transform .16s,border .16s,box-shadow .16s}.tower-card:hover{transform:translateY(-3px);border-color:#c49c59}.tower-card.selected{border-color:#d4a653;box-shadow:0 0 0 1px #d4a6532b,0 5px 15px #10151080}.tower-card.unaffordable{opacity:.48;filter:saturate(.6)}.card-cost{position:absolute;z-index:2;right:5px;top:5px;background:#18211fdd;border:1px solid #d5ab5b66;padding:3px 5px;color:#edc777;font:9px var(--mono)}.card-cost i{font-style:normal}.card-art{height:57px;margin-bottom:8px;display:grid;place-items:center;position:relative;overflow:hidden;background:radial-gradient(circle at 50% 80%,#526145,#324037 57%,#25322d);border:1px solid #ded0ae1b}.card-art:before,.card-art:after{content:'';position:absolute;bottom:-15px;width:65px;height:34px;border-radius:50%;background:#16211c;filter:blur(1px)}.card-art:after{width:37px;height:49px;bottom:-27px;background:#202d24}.art-glow{position:absolute;width:44px;height:44px;border-radius:50%;background:#d7ad5033;filter:blur(9px)}.tower-glyph{position:relative;z-index:1;font-size:29px;color:#e5c27b;text-shadow:0 2px 6px #e6bb6077}.art-sparks{position:absolute;z-index:1;top:7px;left:7px;color:#eacb87aa;font-size:10px;letter-spacing:5px}.cannon-art{background:radial-gradient(circle at 50% 70%,#685341,#393d34 60%,#28312c)}.cannon-art .tower-glyph{color:#c9b394;text-shadow:0 2px 7px #c38b4c}.frost-art{background:radial-gradient(circle at 50% 70%,#496b70,#34464a 60%,#273332)}.frost-art .tower-glyph{color:#a9dce0;text-shadow:0 0 10px #7ce5f6}.frost-art .art-glow{background:#75d8ef4a}.sun-art{background:radial-gradient(circle at 50% 70%,#806843,#474433 60%,#2d342b)}.sun-art .tower-glyph{color:#f3d37d;text-shadow:0 0 11px #ffd65b}.card-name{display:block;font:700 8px var(--sans);letter-spacing:.8px;white-space:nowrap}.card-subtitle{display:block;margin-top:4px;color:#939688;font-size:8px;line-height:1.2;white-space:nowrap;letter-spacing:-.1px}.card-stats{display:flex;justify-content:space-between;border-top:1px solid #ddd0b31c;padding-top:6px;margin-top:7px;color:#899081;font:7px var(--mono);letter-spacing:.25px}.card-stats b{color:#d7bd83;font-weight:500}.deck-tip{border:1px solid #c1a05b33;background:#1b2823;margin-top:10px;height:28px;display:flex;align-items:center;justify-content:center;gap:6px;color:#b8a577;font:8px var(--mono);letter-spacing:.55px}.tip-star{color:#dcb864}.selected-info{margin-top:8px;display:flex;align-items:center;gap:8px;padding:7px 8px;border-left:2px solid #d3a553;background:#26312a;color:#c9bb96}.selected-mark{font-size:16px;color:#ddb35e}.selected-info span:nth-child(2){display:flex;flex-direction:column;gap:3px;flex:1}.selected-info b{font:8px var(--mono);letter-spacing:.4px;color:#e4d3a7}.selected-info small{font:8px var(--sans);color:#9ba08e}.selected-info button{border:0;background:none;color:#938c7c;font-size:17px;cursor:pointer}.side-foot{margin-top:auto;text-align:center;padding:7px 0 0;color:#696f62;font:8px var(--mono);letter-spacing:1.3px}.side-foot span{color:#9b8150;margin:0 5px}.footer{height:37px;border-top:1px solid rgba(220,198,154,.12);display:flex;align-items:center;justify-content:space-between;color:#737b70;font:8px var(--mono);letter-spacing:1.2px}.footer b{color:#a58c59;font-weight:400;margin:0 5px}.footer i{font-style:normal;color:#c8ab6e}.modal-backdrop{position:fixed;inset:0;z-index:10;background:#09110fd9;display:grid;place-items:center;padding:20px;backdrop-filter:blur(5px)}.modal{max-width:490px;width:100%;position:relative;padding:34px 38px 30px;background:linear-gradient(145deg,#22302b,#18221f);border:1px solid #c9a55c66;box-shadow:0 25px 100px #000b}.modal-close{position:absolute;right:15px;top:12px;background:none;border:0;color:#a9a28d;font-size:23px;cursor:pointer}.modal h2{font:700 31px var(--serif);margin:9px 0 7px}.modal>p{font-size:12px;color:#a8a994;line-height:1.65;margin:0}.help-steps{display:grid;gap:0;margin:20px 0}.help-steps div{display:grid;grid-template-columns:32px 1fr;column-gap:9px;padding:12px 0;border-top:1px solid #ddc89922}.help-steps div>span{grid-row:span 2;color:#d8b15f;font:10px var(--mono);padding-top:2px}.help-steps b{font:600 12px var(--serif);color:#eaddc2}.help-steps small{font-size:10px;line-height:1.5;color:#969b8d;margin-top:4px}.modal-cta{width:100%;height:42px;background:#b88743;color:#fff1d2;border:1px solid #e1ba6d;font:700 10px var(--sans);letter-spacing:1.2px;cursor:pointer}.toast{position:fixed;bottom:26px;left:50%;transform:translate(-50%,15px);z-index:20;padding:11px 17px;background:#26342c;border:1px solid #d7ad5c88;color:#f3dba7;font:10px var(--mono);letter-spacing:.5px;opacity:0;transition:.25s;pointer-events:none;box-shadow:0 8px 30px #0008}.toast.show{opacity:1;transform:translate(-50%,0)}
