@media(max-width:520px){.app-shell{padding:0 11px}.topbar{height:59px}.brand{font-size:12px;gap:7px}.brand-mark{width:25px;height:25px}.chapter{margin-left:15px}.chapter-kicker{font-size:7px;letter-spacing:1px}.chapter-name{font-size:11px}.top-actions{gap:9px}.sound-chip{font-size:7px;letter-spacing:.8px}.icon-btn{height:25px;width:25px}.game-layout{padding-top:18px;gap:13px}.battle-heading{height:62px}.battle-heading h1{font-size:23px}.battle-heading .eyebrow{font-size:8px}.battle-state{font-size:7px;letter-spacing:.4px;margin-bottom:10px;gap:4px}.board-frame{padding:6px}.board-topline,.board-legend{padding:0 4px;font-size:7px;letter-spacing:.7px;height:26px}.canvas-wrap{aspect-ratio:1.25}.canvas-tip{font-size:7px;letter-spacing:.6px;padding:7px 8px;bottom:7px}.legend-hint{display:none}.battle-controls{padding-top:9px}.wave-progress{height:39px}.wave-number{font-size:8px}.start-wave{height:39px;padding:0 10px;font-size:8px;gap:6px}.start-wave kbd{display:none}.pause-btn{height:39px;width:37px}.side-column{grid-template-columns:1fr;gap:9px}.resource-panel,.mission-panel,.deck-panel,.side-foot{grid-column:1;grid-row:auto}.resource-panel{padding:11px 13px}.mission-panel{padding:10px 13px}.mission-row{padding:9px 0}.mission-row p{font-size:9px}.resources{padding-top:9px}.resource b{font-size:18px}.resource-divider{margin:0 12px}.deck-panel{padding:11px 9px 9px}.hand{gap:5px;margin-top:9px}.tower-card{padding:5px 4px 6px}.card-cost{font-size:8px;right:3px;top:3px;padding:2px 3px}.card-art{height:49px;margin-bottom:6px}.tower-glyph{font-size:25px}.card-name{font-size:7px;letter-spacing:.35px}.card-subtitle{font-size:7px;letter-spacing:-.2px}.card-stats{font-size:6px;padding-top:5px;margin-top:6px}.deck-tip{font-size:7px;letter-spacing:.2px;height:26px}.selected-info{margin-top:6px}.footer{font-size:7px;letter-spacing:.5px}.footer span:last-child{display:none}.modal{padding:29px 23px 23px}.modal h2{font-size:27px}}

(() => {
  'use strict';
  const canvas = document.getElementById('gameCanvas');
  const ctx = canvas.getContext('2d');
  const W = 900, H = 500, TILE = 50;
  const path = [{x:-30,y:100},{x:170,y:100},{x:230,y:130},{x:260,y:190},{x:300,y:220},{x:410,y:220},{x:455,y:250},{x:480,y:310},{x:530,y:340},{x:650,y:340},{x:700,y:310},{x:730,y:250},{x:780,y:220},{x:930,y:220}];
  const cards = {
    archer:{name:'WATCHTOWER',cost:60,range:155,damage:12,rate:.72,color:'#e6c27b',type:'arrow'},
    cannon:{name:'IRONMOUTH',cost:90,range:112,damage:33,rate:1.55,color:'#d4aa76',type:'cannon'},
    frost:{name:'FROSTWITCH',cost:75,range:128,damage:7,rate:.85,color:'#9ee5e8',type:'frost'},
    sun:{name:'SUN SHRINE',cost:80,range:0,damage:0,rate:8,color:'#f0cf75',type:'sun'}
  };
  let gold=160, lives=20, wave=0, kills=0, towers=[], enemies=[], projectiles=[], particles=[], selected='archer', running=false, paused=false, spawnLeft=0, spawnTimer=0, gameOver=false, gameWon=false, last=performance.now(), toastTimer, hover=null, animTime=0;
  const pathSegments=[]; let pathLength=0;
  for(let i=1;i<path.length;i++){let a=path[i-1],b=path[i],len=Math.hypot(b.x-a.x,b.y-a.y);pathSegments.push({a,b,len,start:pathLength});pathLength+=len;}
  const trees=[]; let seed=92; const rand=()=>{seed=(seed*1664525+1013904223)>>>0;return seed/4294967296};
  for(let i=0;i<120;i++){let x=rand()*W,y=rand()*H;if(distancePath(x,y)>62)trees.push({x,y,r:8+rand()*15,tone:Math.floor(rand()*4),depth:y});}
  function distancePath(x,y){let d=999;for(const s of pathSegments){const vx=s.b.x-s.a.x,vy=s.b.y-s.a.y,t=Math.max(0,Math.min(1,((x-s.a.x)*vx+(y-s.a.y)*vy)/(s.len*s.len)));d=Math.min(d,Math.hypot(x-(s.a.x+t*vx),y-(s.a.y+t*vy)));}return d;}
  function resize(){const rect=canvas.getBoundingClientRect(),dpr=Math.min(window.devicePixelRatio||1,2);canvas.width=Math.round(rect.width*dpr);canvas.height=Math.round(rect.height*dpr);ctx.setTransform(canvas.width/W,0,0,canvas.height/H,0,0);}
  window.addEventListener('resize',resize); resize();
  function atDistance(dist){for(const s of pathSegments){if(dist<=s.start+s.len){let t=(dist-s.start)/s.len;return{x:s.a.x+(s.b.x-s.a.x)*t,y:s.a.y+(s.b.y-s.a.y)*t,angle:Math.atan2(s.b.y-s.a.y,s.b.x-s.a.x)};}}return {...path[path.length-1],angle:0};}
  const clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
  function roundRect(x,y,w,h,r,fill,stroke){ctx.beginPath();ctx.roundRect(x,y,w,h,r);if(fill){ctx.fillStyle=fill;ctx.fill();}if(stroke){ctx.strokeStyle=stroke;ctx.stroke();}}
  function draw(){ctx.clearRect(0,0,W,H);
    const bg=ctx.createLinearGradient(0,0,W,H);bg.addColorStop(0,'#344738');bg.addColorStop(.52,'#304133');bg.addColorStop(1,'#24392f');ctx.fillStyle=bg;ctx.fillRect(0,0,W,H);
    // forest floor flecks
    for(let i=0;i<180;i++){let x=(i*127+13)%W,y=(i*83+21)%H;ctx.fillStyle=i%3===0?'#b4a06412':'#d3d5a50b';ctx.fillRect(x,y,1.5,1.5);}
    // subtle field grid
    ctx.strokeStyle='#c2bd8c0b';ctx.lineWidth=1;for(let x=0;x<=W;x+=TILE){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,H);ctx.stroke();}for(let y=0;y<=H;y+=TILE){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(W,y);ctx.stroke();}
    // clearing glows
    let glow=ctx.createRadialGradient(465,250,30,465,250,440);glow.addColorStop(0,'#8a965215');glow.addColorStop(1,'#18271a00');ctx.fillStyle=glow;ctx.fillRect(0,0,W,H);
    // track shadow, border and road
    strokePath('#15251fc9',92);strokePath('#7f6a4666',78);strokePath('#9b815b',71);strokePath('#b59b6d',62);strokePath('#c1a477',2,'#e1ca935a');
    // path dashes
    ctx.save();ctx.setLineDash([9,13]);ctx.lineDashOffset=-animTime*12;strokePath('#ead29b66',2);ctx.restore();
    // edge brush details
    for(let i=0;i<pathLength;i+=23){const p=atDistance(i),n=i%2?1:-1;for(let s of [-1,1]){const x=p.x+Math.cos(p.angle+Math.PI/2)*n*s*42,y=p.y+Math.sin(p.angle+Math.PI/2)*n*s*42;ctx.fillStyle='#b8aa7745';ctx.beginPath();ctx.ellipse(x,y,2,1.5,p.angle,0,Math.PI*2);ctx.fill();}}
    trees.sort((a,b)=>a.depth-b.depth);trees.forEach(tree=>drawTree(tree));
    drawKeep();
    // placement highlight
    if(hover && selected && !running && !gameOver){const cx=Math.floor(hover.x/TILE)*TILE+TILE/2,cy=Math.floor(hover.y/TILE)*TILE+TILE/2,valid=canPlace(cx,cy,selected,false);ctx.fillStyle=valid?'#c9dd8a20':'#d66e5729';ctx.strokeStyle=valid?'#d8dc9c88':'#e6816b99';ctx.lineWidth=1;ctx.beginPath();ctx.arc(cx,cy,cards[selected].range,0,Math.PI*2);ctx.fill();ctx.stroke();ctx.fillStyle=valid?'#d8d69c22':'#db73552c';ctx.fillRect(Math.floor(hover.x/TILE)*TILE,Math.floor(hover.y/TILE)*TILE,TILE,TILE);}
    towers.forEach(drawTower);enemies.forEach(drawEnemy);projectiles.forEach(drawProjectile);particles.forEach(drawParticle);
    if(paused){ctx.fillStyle='#101b18a8';ctx.fillRect(0,0,W,H);ctx.fillStyle='#f0d79f';ctx.textAlign='center';ctx.font='700 18px "DM Sans"';ctx.fillText('BATTLE PAUSED',W/2,H/2);ctx.font='10px "DM Mono"';ctx.fillStyle='#c7c1aa';ctx.fillText('PRESS RESUME TO CONTINUE',W/2,H/2+23);}
    if(gameOver||gameWon){ctx.fillStyle='#101b18b8';ctx.fillRect(0,0,W,H);ctx.fillStyle=gameWon?'#efd48c':'#e29a7d';ctx.textAlign='center';ctx.font='700 27px "Playfair Display"';ctx.fillText(gameWon?'THE REALM ENDURES':'THE KEEP HAS FALLEN',W/2,H/2-12);ctx.font='11px "DM Mono"';ctx.fillStyle='#e7e0ca';ctx.fillText(gameWon?'A new legend is written in Ashenwood.':'The road is lost. Regroup and try again.',W/2,H/2+15);}
  }
  function strokePath(color,width,stroke){ctx.beginPath();ctx.moveTo(path[0].x,path[0].y);for(let i=1;i<path.length;i++)ctx.lineTo(path[i].x,path[i].y);ctx.lineJoin='round';ctx.lineCap='round';ctx.strokeStyle=color;ctx.lineWidth=width;ctx.stroke();if(stroke){ctx.lineWidth=1;ctx.strokeStyle=stroke;ctx.stroke();}}
  function drawTree(t){const {x,y,r,tone}=t;const shades=['#1b3028','#20372d','#274034','#304735'];ctx.fillStyle='#1a251b55';ctx.beginPath();ctx.ellipse(x+3,y+r*.48,r*.9,r*.42,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#463d2d';ctx.fillRect(x-1.6,y-r*.05,3.2,r*.75);ctx.fillStyle=shades[tone];ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);ctx.fill();ctx.fillStyle=['#48603a','#536343','#526b43','#64724b'][tone];ctx.globalAlpha=.6;ctx.beginPath();ctx.arc(x-r*.2,y-r*.19,r*.65,Math.PI,Math.PI*1.83);ctx.fill();ctx.globalAlpha=1;ctx.fillStyle='#b3b56c25';ctx.beginPath();ctx.arc(x-r*.43,y-r*.48,1.6,0,Math.PI*2);ctx.fill();}
  function drawKeep(){let x=855,y=220;ctx.fillStyle='#171d19aa';ctx.beginPath();ctx.ellipse(x,y+24,40,25,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#62634f';ctx.fillRect(x-26,y-27,52,48);ctx.fillStyle='#827961';ctx.fillRect(x-32,y-35,15,54);ctx.fillRect(x+17,y-35,15,54);ctx.fillStyle='#9a8b68';ctx.fillRect(x-35,y-39,21,6);ctx.fillRect(x+14,y-39,21,6);ctx.fillStyle='#493e2b';ctx.beginPath();ctx.moveTo(x-16,y-27);ctx.lineTo(x,y-48);ctx.lineTo(x+16,y-27);ctx.fill();ctx.fillStyle='#332f25';ctx.fillRect(x-5,y+1,10,20);ctx.fillStyle='#edc46f';ctx.beginPath();ctx.arc(x,y-5,3,0,Math.PI*2);ctx.fill();ctx.fillStyle='#e4ca83';ctx.font='9px "DM Mono"';ctx.textAlign='center';ctx.fillText('THE KEEP',x,y+34);}
  function drawTower(t){const def=cards[t.type],x=t.x,y=t.y;ctx.save();ctx.translate(x,y);if(t.type!=='sun'){ctx.strokeStyle=def.color+'20';ctx.lineWidth=1;ctx.beginPath();ctx.arc(0,0,def.range,0,Math.PI*2);ctx.stroke();}
    ctx.fillStyle='#101d18a8';ctx.beginPath();ctx.ellipse(0,8,19,10,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#635843';ctx.beginPath();ctx.arc(0,2,15,0,Math.PI*2);ctx.fill();ctx.fillStyle='#93815b';ctx.beginPath();ctx.arc(0,0,12,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#d5bc7b';ctx.lineWidth=1.5;ctx.beginPath();ctx.arc(0,0,12,0,Math.PI*2);ctx.stroke();
    if(t.type==='archer'){ctx.fillStyle='#3d5948';ctx.fillRect(-6,-15,12,15);ctx.fillStyle='#81905f';ctx.beginPath();ctx.moveTo(-10,-13);ctx.lineTo(0,-26);ctx.lineTo(10,-13);ctx.closePath();ctx.fill();ctx.fillStyle='#d3bb7e';ctx.fillRect(-3,-8,6,6);ctx.strokeStyle='#ecd8a4';ctx.lineWidth=1.5;ctx.beginPath();ctx.arc(0,-12,7,Math.PI,Math.PI*2);ctx.stroke();}
    else if(t.type==='cannon'){ctx.fillStyle='#53534a';ctx.beginPath();ctx.arc(0,-7,8,0,Math.PI*2);ctx.fill();ctx.save();ctx.rotate(t.angle||-.5);ctx.fillStyle='#302f2a';roundRect(-4,-21,8,19,3,'#45443c','#c3a77c');ctx.restore();ctx.fillStyle='#d3b172';ctx.beginPath();ctx.arc(0,-7,3,0,Math.PI*2);ctx.fill();}
    else if(t.type==='frost'){ctx.fillStyle='#456b6e';ctx.beginPath();ctx.moveTo(0,-27);ctx.lineTo(9,-12);ctx.lineTo(0,-5);ctx.lineTo(-9,-12);ctx.closePath();ctx.fill();ctx.strokeStyle='#b1eff0';ctx.lineWidth=1.5;ctx.stroke();ctx.fillStyle='#d5ffff';ctx.beginPath();ctx.arc(0,-14,3,0,Math.PI*2);ctx.fill();}
    else{ctx.strokeStyle='#e8cc77';ctx.lineWidth=3;ctx.beginPath();ctx.arc(0,-12,7,0,Math.PI*2);ctx.stroke();ctx.fillStyle='#fff0ab';ctx.beginPath();ctx.arc(0,-12,4,0,Math.PI*2);ctx.fill();for(let i=0;i<8;i++){let a=i*Math.PI/4;ctx.strokeStyle='#dfbd62';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(Math.cos(a)*10,-12+Math.sin(a)*10);ctx.lineTo(Math.cos(a)*14,-12+Math.sin(a)*14);ctx.stroke();}}
    if(t.level>1){ctx.fillStyle='#f0d274';ctx.font='9px "DM Mono"';ctx.textAlign='center';ctx.fillText('+'+(t.level-1),0,24);}ctx.restore();}
  function drawEnemy(e){ctx.save();ctx.translate(e.x,e.y);ctx.rotate(e.angle||0);const colors=e.kind==='brute'?['#65433a','#c27a5c']:e.kind==='wisp'?['#42636a','#9ee4df']:['#584837','#d0a76e'];ctx.fillStyle='#142019aa';ctx.beginPath();ctx.ellipse(0,9,e.kind==='brute'?12:8,4,0,0,Math.PI*2);ctx.fill();ctx.fillStyle=colors[0];ctx.beginPath();ctx.arc(0,0,e.kind==='brute'?10:7,0,Math.PI*2);ctx.fill();ctx.fillStyle=colors[1];ctx.beginPath();ctx.arc(1,-2,e.kind==='brute'?5:3.5,0,Math.PI*2);ctx.fill();ctx.fillStyle='#f3d996';ctx.beginPath();ctx.arc(2,-3,1.1,0,Math.PI*2);ctx.fill();ctx.restore();if(e.hp<e.maxHp){ctx.fillStyle='#20271e';ctx.fillRect(e.x-9,e.y-14,18,2);ctx.fillStyle=e.kind==='brute'?'#d78065':'#c6ba78';ctx.fillRect(e.x-9,e.y-14,18*clamp(e.hp/e.maxHp,0,1),2);}}
  function drawProjectile(p){ctx.save();ctx.fillStyle=p.color;ctx.shadowColor=p.color;ctx.shadowBlur=9;ctx.beginPath();ctx.arc(p.x,p.y,p.type==='cannon'?4:2.5,0,Math.PI*2);ctx.fill();if(p.type==='arrow'){ctx.translate(p.x,p.y);ctx.rotate(Math.atan2(p.vy,p.vx));ctx.fillRect(-5,-1,8,2);}ctx.restore();}
  function drawParticle(p){ctx.globalAlpha=clamp(p.life/p.max,0,1);ctx.fillStyle=p.color;ctx.beginPath();ctx.arc(p.x,p.y,p.r*clamp(p.life/p.max,.2,1),0,Math.PI*2);ctx.fill();ctx.globalAlpha=1;}
  function canPlace(x,y,type,show=true){if(x<35||x>820||y<30||y>470)return false;if(distancePath(x,y)<65)return false;if(towers.some(t=>Math.hypot(t.x-x,t.y-y)<38))return false;if(type==='sun'&&towers.filter(t=>t.type==='sun').length>=3)return false;return true;}
  function updateUI(){document.getElementById('goldValue').textContent=gold;document.getElementById('lifeValue').textContent=lives;document.getElementById('killCount').textContent=kills;document.getElementById('waveCount').innerHTML=`WAVE <b>${Math.min(wave,8)}</b> / 8`;document.getElementById('enemyCount').textContent=running?`${enemies.length+spawnLeft} HOSTILE${enemies.length+spawnLeft===1?'':'S'}`:wave>=8?'REALM SECURED':'NO HOSTILES';document.getElementById('progressFill').style.width=`${wave/8*100}%`;document.getElementById('threatLevel').textContent=['I','II','III','IV','V','VI','VII','VIII'][Math.max(0,wave-1)]||'I';document.getElementById('turnNum').textContent=String(Math.min(wave+1,9)).padStart(2,'0');document.querySelectorAll('.tower-card').forEach(el=>{el.classList.toggle('selected',el.dataset.type===selected);el.classList.toggle('unaffordable',gold<cards[el.dataset.type].cost);});const start=document.getElementById('startWave');start.disabled=running||gameOver||gameWon||wave>=8;start.innerHTML=gameWon?'<span class="play-icon">✦</span><span>VICTORY</span>':gameOver?'<span class="play-icon">×</span><span>DEFEATED</span>':wave>=8?'<span class="play-icon">✦</span><span>REALM SECURED</span>':running?'<span class="play-icon">⚔</span><span>WAVE IN PROGRESS</span>':`<span class="play-icon">▶</span><span>${wave===0?'BEGIN WAVE':'NEXT WAVE'}</span><kbd>SPACE</kbd>`;document.getElementById('pauseBtn').textContent=paused?'▶':'Ⅱ';document.getElementById('pauseBtn').setAttribute('aria-label',paused?'Resume game':'Pause game');}
  function toast(msg){const el=document.getElementById('toast');el.textContent=msg;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2100);}
  function select(type){selected=type;const label=document.getElementById('selectedInfo');label.querySelector('b').textContent=cards[type].name+' SELECTED';label.querySelector('small').innerHTML=`Click an open tile to place · <kbd>${['archer','cannon','frost','sun'].indexOf(type)+1}</kbd>`;document.getElementById('canvasTip').classList.remove('hidden');updateUI();}
  document.querySelectorAll('.tower-card').forEach(el=>el.addEventListener('click',()=>select(el.dataset.type)));
  canvas.addEventListener('pointermove',ev=>{const r=canvas.getBoundingClientRect();hover={x:(ev.clientX-r.left)/r.width*W,y:(ev.clientY-r.top)/r.height*H};});canvas.addEventListener('pointerleave',()=>hover=null);
  canvas.addEventListener('pointerdown',ev=>{if(!selected||running||paused||gameOver||gameWon)return;const r=canvas.getBoundingClientRect(),x=Math.floor(((ev.clientX-r.left)/r.width*W)/TILE)*TILE+TILE/2,y=Math.floor(((ev.clientY-r.top)/r.height*H)/TILE)*TILE+TILE/2;if(!canPlace(x,y,selected)){toast('That ground is too treacherous for a defense.');return;}const def=cards[selected];if(gold<def.cost){toast(`You need ${def.cost-gold} more gold.`);return;}gold-=def.cost;towers.push({x,y,type:selected,cooldown:.2,angle:0,level:1,yieldTimer:8});document.getElementById('canvasTip').classList.add('hidden');updateUI();});
  document.getElementById('startWave').addEventListener('click',startWave);
  function startWave(){if(running||gameOver||gameWon||wave>=8)return;wave++;running=true;paused=false;spawnLeft=5+wave*2;spawnTimer=.45;document.getElementById('statusText').textContent=`WAVE ${wave} · ENEMIES APPROACH`;document.getElementById('missionTitle').textContent=['','Scouts on the road','The raiders gather','A heavier host','The dead march','Wolves at the gate','Iron and ash','The last legion','The final assault'][wave]||'The enemy advances';document.getElementById('missionCopy').textContent=`Wave ${wave} is upon us. ${spawnLeft} hostiles are moving through Ashenwood.`;const banner=document.getElementById('waveBanner');banner.innerHTML=`WAVE <b>${wave}</b> INCOMING`;banner.classList.remove('hidden');setTimeout(()=>banner.classList.add('hidden'),1800);updateUI();}
  document.getElementById('pauseBtn').addEventListener('click',()=>{if(!running)return;paused=!paused;updateUI();});document.getElementById('cancelPlacement').addEventListener('click',()=>{selected=null;document.getElementById('canvasTip').classList.add('hidden');document.querySelectorAll('.tower-card').forEach(e=>e.classList.remove('selected'));});
  const backdrop=document.getElementById('modalBackdrop');function showHelp(){backdrop.classList.remove('hidden');}function hideHelp(){backdrop.classList.add('hidden');}document.getElementById('helpBtn').addEventListener('click',showHelp);document.getElementById('deckHelp').addEventListener('click',showHelp);document.getElementById('modalClose').addEventListener('click',hideHelp);document.getElementById('modalOk').addEventListener('click',hideHelp);backdrop.addEventListener('click',e=>{if(e.target===backdrop)hideHelp();});
  window.addEventListener('keydown',e=>{if(e.key==='Escape'){hideHelp();return;}if(e.code==='Space'){e.preventDefault();if(!backdrop.classList.contains('hidden'))return;if(running){paused=!paused;updateUI();}else startWave();}if(['1','2','3','4'].includes(e.key))select(['archer','cannon','frost','sun'][Number(e.key)-1]);});
  function update(dt){animTime+=dt;if(!paused){if(running){spawnTimer-=dt;if(spawnLeft>0&&spawnTimer<=0){spawnEnemy();spawnLeft--;spawnTimer=Math.max(.4,1.05-wave*.045);}for(const e of enemies){let slow=e.slow>0?e.slowFactor:1;e.slow=Math.max(0,e.slow-dt);e.dist+=e.speed*slow*dt;const p=atDistance(e.dist);e.x=p.x;e.y=p.y;e.angle=p.angle;if(e.dist>=pathLength){e.dead=true;lives-=e.kind==='brute'?2:1;makeBurst(e.x,e.y,'#d8876b',9);if(lives<=0){lives=0;gameOver=true;running=false;document.getElementById('statusText').textContent='THE KEEP HAS FALLEN';document.getElementById('missionTitle').textContent='The gate is breached';document.getElementById('missionCopy').textContent='The realm has fallen. Reset the page to try a new defense.';}}}
      enemies=enemies.filter(e=>!e.dead);
      towers.forEach(t=>{if(t.type==='sun'){t.yieldTimer-=dt;if(t.yieldTimer<=0){gold+=8+(wave>0?Math.floor(wave/3):0);t.yieldTimer=8;makeBurst(t.x,t.y-13,'#edcc76',5);updateUI();}return;}t.cooldown-=dt;if(t.cooldown<=0){const target=enemies.filter(e=>Math.hypot(e.x-t.x,e.y-t.y)<cards[t.type].range).sort((a,b)=>b.dist-a.dist)[0];if(target){t.angle=Math.atan2(target.y-t.y,target.x-t.x);t.cooldown=cards[t.type].rate*(t.level===2?.8:1);projectiles.push({x:t.x,y:t.y-12,target,speed:t.type==='cannon'?270:410,damage:cards[t.type].damage*(t.level===2?1.55:1),type:cards[t.type].type,color:cards[t.type].color});}}});
      projectiles.forEach(p=>{if(!p.target||p.target.dead){p.dead=true;return;}const dx=p.target.x-p.x,dy=p.target.y-p.y,d=Math.hypot(dx,dy),step=p.speed*dt;if(d<step+4){p.target.hp-=p.damage;p.dead=true;if(p.type==='frost'){p.target.slow=1.45;p.target.slowFactor=.55;}makeBurst(p.target.x,p.target.y,p.color,3);if(p.target.hp<=0){p.target.dead=true;kills++;gold+=p.target.kind==='brute'?11:6;makeBurst(p.target.x,p.target.y,p.target.kind==='wisp'?'#9ee4df':'#d9b469',8);updateUI();}}else{p.x+=dx/d*step;p.y+=dy/d*step;}});projectiles=projectiles.filter(p=>!p.dead);enemies=enemies.filter(e=>!e.dead);
      if(spawnLeft===0&&enemies.length===0&&!gameOver){running=false;gold+=35+wave*5;document.getElementById('statusText').textContent=wave===8?'THE REALM ENDURES':'WAVE CLEARED · +'+(35+wave*5)+' GOLD';document.getElementById('missionTitle').textContent=wave===8?'Ashenwood is safe':'The road is quiet';document.getElementById('missionCopy').textContent=wave===8?'The old road is held. The realm will remember.':'The attackers have been driven back. Your reserves have been replenished.';if(wave===8){gameWon=true;document.getElementById('statusText').textContent='VICTORY · ASHENWOOD IS SAFE';}updateUI();}
    }particles.forEach(p=>{p.life-=dt;p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=14*dt;});particles=particles.filter(p=>p.life>0);}
  }
  function spawnEnemy(){let kind=wave>=4&&Math.random()<.2?'brute':wave>=3&&Math.random()<.18?'wisp':'raider';let hp=(kind==='brute'?100:kind==='wisp'?42:48)+wave*(kind==='brute'?21:11);enemies.push({dist:0,x:path[0].x,y:path[0].y,angle:0,hp,maxHp:hp,kind,speed:(kind==='brute'?29:kind==='wisp'?47:38)+wave*1.7,slow:0,slowFactor:1,dead:false});updateUI();}
  function makeBurst(x,y,color,n){for(let i=0;i<n;i++){let a=Math.random()*Math.PI*2,s=20+Math.random()*65;particles.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s-18,r:1+Math.random()*2,life:.3+Math.random()*.4,max:.7,color});}}
  function frame(now){let dt=Math.min(.04,(now-last)/1000);last=now;update(dt);draw();requestAnimationFrame(frame);}requestAnimationFrame(frame);updateUI();
  // Tutorial overlay on first visit, with the opening placement still visible.
  setTimeout(showHelp,450);
})();

